def is_samepatterns(values, patterns):
    if len(values) != len(patterns):
        return False

    value_to_pattern = {}
    pattern_to_value = {}

    for value, pattern in zip(values, patterns):
        if value in value_to_pattern and value_to_pattern[value] != pattern:
            return False
        if pattern in pattern_to_value and pattern_to_value[pattern] != value:
            return False

        value_to_pattern[value] = pattern
        pattern_to_value[pattern] = value

    return True
